// ─── File: ContractFirstDemo.java ───
// Runnable demo: a spec-diff CI gate accepts additive change, rejects breaking change.
package com.bank.contractfirst;

import java.util.*;
import java.util.logging.*;

public class ContractFirstDemo {

    private static final Logger log = Logger.getLogger("ContractFirst");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Baseline spec: TransferResponse has transferId + status.
        ApiSpec baseline = new ApiSpec(
                "TransferResponse", Set.of("transferId", "status"), Set.of("transferId", "status"));

        SpecDiffer differ = new SpecDiffer();

        // Proposed change 1: ADD optional field 'feeCharged' → compatible.
        ApiSpec additive = new ApiSpec(
                "TransferResponse", Set.of("transferId", "status", "feeCharged"),
                Set.of("transferId", "status"));
        boolean ok1 = differ.isCompatible(baseline, additive);
        log.info(() -> "CI gate — additive change (feeCharged) compatible? " + ok1);

        // Proposed change 2: RENAME transferId → txnId (remove required field) → breaking.
        ApiSpec breaking = new ApiSpec(
                "TransferResponse", Set.of("txnId", "status"), Set.of("txnId", "status"));
        boolean ok2 = differ.isCompatible(baseline, breaking);
        if (ok2) log.info("CI gate — change compatible");
        else log.severe("CI gate — BREAKING change rejected BEFORE code is written: "
                + "'transferId' removed. Bump version or keep the field.");

        // The controller implements the GENERATED interface → compile-time safety.
        TransferApi api = new TransferController();
        log.info(() -> "Controller implements generated TransferApi: "
                + api.createTransfer("SAV2001", "CUR3001", "50000"));
    }
}

// ─── spec/ApiSpec.java (models one schema's fields + which are required) ───
class ApiSpec {
    final String schemaName; final Set<String> fields; final Set<String> requiredFields;
    ApiSpec(String name, Set<String> fields, Set<String> required) {
        this.schemaName = name; this.fields = fields; this.requiredFields = required;
    }
}

// ─── spec/SpecDiffer.java (the CI breaking-change gate) ───
class SpecDiffer {
    // Compatible if: no required field removed AND no previously-optional field became required.
    boolean isCompatible(ApiSpec oldSpec, ApiSpec newSpec) {
        // Removing a field that old consumers rely on is breaking.
        for (String f : oldSpec.fields)
            if (!newSpec.fields.contains(f)) return false;      // field removed → breaking
        // Making a new field required (that old producers won't send) is breaking.
        for (String r : newSpec.requiredFields)
            if (!oldSpec.fields.contains(r)) return false;      // new required field → breaking
        return true;   // only additions of optional fields → compatible
    }
}

// ─── generated/TransferApi.java (GENERATED-style interface from the spec) ───
interface TransferApi {
    // In real openapi-generator output this is a Spring interface with @PostMapping etc.
    String createTransfer(String fromAccount, String toAccount, String amount);
}

// ─── controller/TransferController.java (implements the generated contract) ───
class TransferController implements TransferApi {
    @Override public String createTransfer(String from, String to, String amount) {
        // If the spec changes the signature, THIS no longer compiles → drift caught at build.
        return "{transferId=TXF-00001, status=COMPLETED}";
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
